#include <iostream>
#include <numeric>   // std::accumulate
#include <thread>    // std::thread
#include <vector>

int main() {
    std::vector<int> datos(1'000'000, 1);      // un millón de unos
    long long suma1 = 0, suma2 = 0;           // un resultado POR hilo: no se comparten

    auto mitad = datos.begin() + datos.size() / 2;

    // Hilo 1: suma la primera mitad. Captura por referencia [&] para escribir en suma1.
    std::thread t1([&] { suma1 = std::accumulate(datos.begin(), mitad, 0LL); });
    // Hilo 2: suma la segunda mitad en paralelo con t1.
    std::thread t2([&] { suma2 = std::accumulate(mitad, datos.end(), 0LL); });

    t1.join();   // esperamos a que t1 termine...
    t2.join();   // ...y a que t2 termine, antes de leer sus resultados

    std::cout << suma1 + suma2 << '\n';   // 1000000: siempre el mismo resultado
}

